entries[46887] = { ["name"] = "Bountiful Feast", ["text"] = "Requires Cooking (350)\nRequires Pilgrim's Bounty\nUse: Set out a bountiful feast to feed a very hungry party. Restores 4% health and mana every sec for 30 sec. If you spend at least 10 sec eating you will become well fed and gain [floor(cond([source value]( 90, 15), 90 - 15, 0) * 1.108) + 8] attack power, [floor(cond([source value]( 90, 15), 90 - 15, 0) * 0.6616) + 4] spell power, and [floor(cond([source value]( 90, 15), 90 - 15, 0) * 0.554) + 4] Stamina for 1 hour.\nSell Price:", ["unresolvedValues"] = true }
